#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "posix_compat.h"
#include "production.h"
#define ROOT "state/investigation"
#define IM_DIR ROOT "/im"
#define INDEX ROOT "/im.index.tsv"
#define REVIEWS ROOT "/im.reviews.tsv"
#define APPROVALS ROOT "/im.approvals.tsv"
#define FEEDBACK ROOT "/im.feedback.tsv"
#define RELATIONS ROOT "/evidence-relationships.tsv"
#define INVESTIGATIONS ROOT "/investigations.tsv"
#define INT_RECORDS "intelligence.records"
static unsigned long hash_text(const char *s){unsigned long h=2166136261UL;while(s&&*s){h^=(unsigned char)*s++;h*=16777619UL;}return h;}
static void now(char out[32]){time_t current=time(NULL);struct tm utc;if(current!=(time_t)-1&&gmtime_r(&current,&utc)!=NULL)strftime(out,32,"%Y-%m-%dT%H:%M:%SZ",&utc);else out[0]='\0';}
static int valid(const char *s,const char *prefix){return s&&prefix&&_strnicmp(s,prefix,strlen(prefix))==0&&s[strlen(prefix)]!='\0'&&strchr(s,'\t')==NULL&&strchr(s,'\r')==NULL&&strchr(s,'\n')==NULL;}
static int active_candidate(const char *candidate){FILE *f=NULL;char line[128],intel[32],can[32],state[16];if(fopen_s(&f,INVESTIGATIONS,"r")!=0||!f)return 0;while(fgets(line,sizeof(line),f))if(sscanf(line,"%31s\t%31s\t%15s",intel,can,state)==3&&_stricmp(can,candidate)==0&&_stricmp(state,"ACTIVE")==0){fclose(f);return 1;}fclose(f);return 0;}
static int source_for(const char *int_id,char out[128]){FILE *f=NULL;char *line;if(!int_id||!out)return 0;line=(char*)malloc(65536);if(!line)return 0;if(fopen_s(&f,INT_RECORDS,"r")!=0||!f){free(line);return 0;}while(fgets(line,65536,f)){char *ctx=NULL,*id=strtok_s(line,"\t",&ctx),*source=strtok_s(NULL,"\t",&ctx);if(id&&source&&_stricmp(id,int_id)==0){strcpy_s(out,128,source);fclose(f);free(line);return 1;}}fclose(f);free(line);return 0;}
int rictus_im_posture(const char *candidate,rictus_im_evidence_posture_t *p){FILE *f=NULL;char line[512],can[32],intel[32],rel[32],rule[128],stamp[32],hash[65],source[128],independent[16][128];size_t independent_count=0,i;if(!valid(candidate,"CAN-")||!p)return 0;memset(p,0,sizeof(*p));if(fopen_s(&f,RELATIONS,"r")!=0||!f)return 1;while(fgets(line,sizeof(line),f))if(sscanf(line,"v=1\t%31s\t%31s\t%31s\t%127[^\t]\t%31s\t%64s",can,intel,rel,rule,stamp,hash)==6&&_stricmp(can,candidate)==0){if(_stricmp(rel,"SUPPORTING")==0)++p->supporting;else if(_stricmp(rel,"OPPOSING")==0)++p->opposing;else if(_stricmp(rel,"CONTRADICTORY")==0)++p->contradictory;else if(_stricmp(rel,"NEGATIVE")==0)++p->negative;else if(_stricmp(rel,"DUPLICATE")==0)++p->duplicate;else ++p->contextual;if(source_for(intel,source)){if(_stricmp(source,"STN-LABZ Threat API")==0)++p->sensors;else{for(i=0;i<independent_count;++i)if(_stricmp(independent[i],source)==0)break;if(i==independent_count&&independent_count<16){strcpy_s(independent[independent_count++],128,source);}}}}fclose(f);p->independent_sources=(unsigned int)independent_count;return 1;}
static int index_find(const char *id,char candidate[32]){FILE *f=NULL;char line[160],im[32],can[32],state[16],stamp[32];if(fopen_s(&f,INDEX,"r")!=0||!f)return 0;while(fgets(line,sizeof(line),f))if(sscanf(line,"%31s\t%31s\t%15s\t%31s",im,can,state,stamp)==4&&_stricmp(im,id)==0){strcpy_s(candidate,32,can);fclose(f);return 1;}fclose(f);return 0;}
static int reviewed_pass(const char *id){FILE *f=NULL;char line[160],im[32],result[16];int pass=0;if(fopen_s(&f,REVIEWS,"r")!=0||!f)return 0;while(fgets(line,sizeof(line),f))if(sscanf(line,"%31s\t%15s",im,result)==2&&_stricmp(im,id)==0)pass=_stricmp(result,"PASS")==0;fclose(f);return pass;}
static int approved(const char *id){FILE *f=NULL;char line[160],im[32];if(fopen_s(&f,APPROVALS,"r")!=0||!f)return 0;while(fgets(line,sizeof(line),f))if(sscanf(line,"%31s",im)==1&&_stricmp(im,id)==0){fclose(f);return 1;}fclose(f);return 0;}
int rictus_im_draft(const char *candidate,const char *operator_name,char id[32],char *reason,size_t reason_size){rictus_im_evidence_posture_t p;FILE *f=NULL;char path[1024],stamp[32],key[128];if(!valid(candidate,"CAN-")||!operator_name||!id||!reason)return 0;if(!active_candidate(candidate)){strcpy_s(reason,reason_size,"Candidate is not under an active operator-authorized watch.");return 0;}if(!rictus_im_posture(candidate,&p)||p.supporting<2){strcpy_s(reason,reason_size,"Threshold not met: at least two explainable supporting relationships are required.");return 0;}if(mkdir("state",0750)!=0&&errno!=EEXIST)return 0;if(mkdir(ROOT,0750)!=0&&errno!=EEXIST)return 0;if(mkdir(IM_DIR,0750)!=0&&errno!=EEXIST)return 0;sprintf_s(key,sizeof(key),"%s|%u|%u|%u",candidate,p.supporting,p.contradictory,p.independent_sources);sprintf_s(id,32,"IM-DRAFT-%08lX",hash_text(key));sprintf_s(path,sizeof(path),"%s/%s.md",IM_DIR,id);if(access(path,F_OK)==0){strcpy_s(reason,reason_size,"An IM draft already exists for this evidence state.");return 0;}now(stamp);if(fopen_s(&f,path,"wb")!=0||!f)return 0;fprintf(f,"# Intelligence Memorandum Draft %s\n\n- Candidate: %s\n- Requested by: %s\n- Created: %s\n- Status: DRAFT / HUMAN APPROVAL REQUIRED\n- Publication: NOT AUTHORIZED\n\n## Decision Requirement\n\nDetermine what the accumulated evidence establishes and what decision, if any, requires human consideration.\n\n## Key Judgment\n\nThe watched candidate has gained material supporting evidence. Applicability and intent remain bounded by the evidence described below.\n\n## Likelihood and Confidence\n\n- Likelihood: %s\n- Confidence: %s\n\n## Evidence Posture\n\n- Supporting: %u\n- Opposing: %u\n- Contradictory: %u\n- Negative: %u\n- Duplicate: %u\n- Contextual: %u\n- STN-LABZ sensor observations: %u\n- Independent external sources: %u\n\n## Alternatives\n\n1. The observations are commodity activity rather than deliberate targeting.\n2. Repetition reflects shared sensors or syndicated reporting rather than independent corroboration.\n3. The condition does not apply to the deployed environment.\n\n## Assumptions and Unknowns\n\nActor identity, intent, affected-version applicability, exposure, exploitability, and compromise are not established unless explicitly supported by retained evidence.\n\n## Contradictory and Negative Evidence\n\nContradictory=%u; negative=%u. These counts remain visible and are not silently resolved.\n\n## Collection Gaps\n\nDeployed-version mapping, sensor identity, outcome semantics, and independent corroboration remain collection requirements where unresolved.\n\n## Warning History\n\nConsult durable WARN records associated with retained INT evidence.\n\n## Authority Boundary\n\nThis is a draft analytical product. It does not approve publication, attribution, remediation, SRT promotion, scope expansion, external contact, or lifecycle transition.\n",id,candidate,operator_name,stamp,p.supporting>=3?"LIKELY":"ROUGHLY EVEN",p.independent_sources?"MODERATE":"LOW",p.supporting,p.opposing,p.contradictory,p.negative,p.duplicate,p.contextual,p.sensors,p.independent_sources,p.contradictory,p.negative);fclose(f);if(fopen_s(&f,INDEX,"a")!=0||!f){unlink(path);return 0;}fprintf(f,"%s\t%s\tDRAFT\t%s\n",id,candidate,stamp);fclose(f);strcpy_s(reason,reason_size,"Draft created; automated review and direct human approval remain required.");return 1;}
int rictus_im_show(const char *id,char *summary,size_t a,char *detail,size_t b){char candidate[32];rictus_im_evidence_posture_t p;if(!index_find(id,candidate)||!rictus_im_posture(candidate,&p))return 0;sprintf_s(summary,a,"%s | candidate=%s | review=%s | approved=%s",id,candidate,reviewed_pass(id)?"PASS":"NOT PASSED",approved(id)?"YES":"NO");sprintf_s(detail,b,"supporting=%u contradictory=%u negative=%u sensors=%u independent sources=%u | publication=NOT AUTHORIZED",p.supporting,p.contradictory,p.negative,p.sensors,p.independent_sources);return 1;}
int rictus_im_review(const char *id,char *result,size_t size){FILE *f=NULL;char candidate[32],stamp[32];rictus_im_evidence_posture_t p;int pass;if(!index_find(id,candidate)||!rictus_im_posture(candidate,&p))return 0;pass=p.supporting>=2;now(stamp);if(fopen_s(&f,REVIEWS,"a")!=0||!f)return 0;fprintf(f,"%s\t%s\t%s\tjudgment-evidence-separated=PASS\talternatives=PASS\tassumptions=PASS\tuncertainty=PASS\tsource-independence=PASS\tauthority=PASS\n",id,pass?"PASS":"FAIL",stamp);fclose(f);sprintf_s(result,size,"Review %s | evidence threshold=%s | alternatives/assumptions/uncertainty/source independence/authority=PASS",pass?"PASS":"FAIL",pass?"PASS":"FAIL");return 1;}
int rictus_im_approve(const char *id,const char *operator_name,char *result,size_t size){FILE *f=NULL;char candidate[32],stamp[32];if(!index_find(id,candidate))return 0;if(!reviewed_pass(id)){strcpy_s(result,size,"Approval refused: automated analytic review has not passed.");return 0;}if(approved(id)){strcpy_s(result,size,"Approval already recorded.");return 1;}now(stamp);if(fopen_s(&f,APPROVALS,"a")!=0||!f)return 0;fprintf(f,"%s\t%s\t%s\tAPPROVED_FOR_HUMAN_USE\tPUBLICATION_NOT_AUTHORIZED\n",id,operator_name,stamp);fclose(f);strcpy_s(result,size,"Human approval recorded. Publication, SRT transition, and operational action remain unauthorized.");return 1;}
int rictus_im_feedback(const char *id,const char *operator_name,const char *feedback,char *result,size_t size){FILE *f=NULL;char candidate[32],stamp[32];if(!index_find(id,candidate)||!feedback||strchr(feedback,'\t')||strchr(feedback,'\r')||strchr(feedback,'\n'))return 0;now(stamp);if(fopen_s(&f,FEEDBACK,"a")!=0||!f)return 0;fprintf(f,"%s\t%s\t%s\t%s\n",id,operator_name,stamp,feedback);fclose(f);strcpy_s(result,size,"Feedback appended; historical judgment was not rewritten.");return 1;}
static unsigned int count_lines(const char *path,const char *token){FILE *f=NULL;char line[512];unsigned int n=0;if(fopen_s(&f,path,"r")!=0||!f)return 0;while(fgets(line,sizeof(line),f))if(!token||strstr(line,token))++n;fclose(f);return n;}
void rictus_im_metrics(rictus_im_metrics_t *m){if(!m)return;memset(m,0,sizeof(*m));m->drafts=count_lines(INDEX,NULL);m->reviews_passed=count_lines(REVIEWS,"\tPASS\t");m->reviews_failed=count_lines(REVIEWS,"\tFAIL\t");m->approvals=count_lines(APPROVALS,NULL);m->feedback_items=count_lines(FEEDBACK,NULL);}
